/**
 * Minimal NOSTR utilities for SignedByMe demo
 * 
 * Full signing capabilities require nostr-tools.
 * This stub provides basic utilities for the demo.
 * 
 * For production enrollment (signing kind 28200 events), 
 * bundle the full nostr-tools library or use server-side signing.
 */

(function(global) {
    'use strict';
    
    // NIP-19 bech32 decoder (minimal implementation)
    const BECH32_ALPHABET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';
    
    function bech32Decode(str) {
        str = str.toLowerCase();
        const pos = str.lastIndexOf('1');
        if (pos < 1 || pos + 7 > str.length) {
            throw new Error('Invalid bech32 string');
        }
        
        const hrp = str.substring(0, pos);
        const data = [];
        
        for (let i = pos + 1; i < str.length; i++) {
            const c = BECH32_ALPHABET.indexOf(str[i]);
            if (c === -1) throw new Error('Invalid bech32 character');
            data.push(c);
        }
        
        // Remove checksum (last 6 characters)
        const dataWithoutChecksum = data.slice(0, -6);
        
        // Convert from 5-bit to 8-bit
        const bytes = convertBits(dataWithoutChecksum, 5, 8, false);
        
        return { hrp, bytes: new Uint8Array(bytes) };
    }
    
    function convertBits(data, fromBits, toBits, pad) {
        let acc = 0;
        let bits = 0;
        const result = [];
        const maxv = (1 << toBits) - 1;
        
        for (const value of data) {
            acc = (acc << fromBits) | value;
            bits += fromBits;
            while (bits >= toBits) {
                bits -= toBits;
                result.push((acc >> bits) & maxv);
            }
        }
        
        if (pad && bits > 0) {
            result.push((acc << (toBits - bits)) & maxv);
        }
        
        return result;
    }
    
    function bytesToHex(bytes) {
        return Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join('');
    }
    
    function hexToBytes(hex) {
        const bytes = new Uint8Array(hex.length / 2);
        for (let i = 0; i < bytes.length; i++) {
            bytes[i] = parseInt(hex.substr(i * 2, 2), 16);
        }
        return bytes;
    }
    
    // NIP-19 decode
    function nip19Decode(str) {
        const { hrp, bytes } = bech32Decode(str);
        
        if (hrp === 'nsec') {
            return { type: 'nsec', data: bytes };
        } else if (hrp === 'npub') {
            return { type: 'npub', data: bytes };
        } else if (hrp === 'note') {
            return { type: 'note', data: bytes };
        } else {
            throw new Error(`Unknown prefix: ${hrp}`);
        }
    }
    
    // SHA-256 using Web Crypto
    async function sha256(message) {
        const msgBuffer = new TextEncoder().encode(message);
        const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
        return new Uint8Array(hashBuffer);
    }
    
    // Compute NOSTR event ID (NIP-01)
    async function computeEventId(event) {
        const serialized = JSON.stringify([
            0,
            event.pubkey,
            event.created_at,
            event.kind,
            event.tags,
            event.content
        ]);
        const hash = await sha256(serialized);
        return bytesToHex(hash);
    }
    
    // Export minimal API
    global.nostrUtils = {
        nip19: {
            decode: nip19Decode
        },
        computeEventId: computeEventId,
        bytesToHex: bytesToHex,
        hexToBytes: hexToBytes,
        
        // Stub for signing - requires full nostr-tools
        finalizeEvent: async function(template, privateKey) {
            throw new Error(
                'Event signing requires nostr-tools. ' +
                'For production, bundle nostr-tools or use server-side signing.'
            );
        }
    };
    
    // Also expose for compatibility with nostr-tools import pattern
    global.nip19 = global.nostrUtils.nip19;
    global.nostrFinalizeEvent = global.nostrUtils.finalizeEvent;
    
})(typeof window !== 'undefined' ? window : global);
